 1→package agents
 2→
 3→import (
 4→	"context"
 5→	"time"
 6→)
 7→
 8→type Output struct {
 9→	Command  string
10→	Stdout   string
11→	Stderr   string
12→	ExitCode int
13→}
14→
15→type Option func(*runConfig)
16→type runConfig struct {
17→	Model          string
18→	PermissionMode string
19→}
20→
21→func WithModel(model string) Option {
22→	return func(c *runConfig) { c.Model = model }
23→}
24→
25→func WithPermissionMode(mode string) Option {
26→	return func(c *runConfig) { c.PermissionMode = mode }
27→}
28→
29→type Agent interface {
30→	Name() string
31→	EntireAgent() string
32→	PromptPattern() string
33→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
34→	// Slower agents (e.g. Gemini) return values > 1.
35→	TimeoutMultiplier() float64
36→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
37→	StartSession(ctx context.Context, dir string) (Session, error)
38→}
39→
40→type Session interface {
41→	Send(input string) error
42→	WaitFor(pattern string, timeout time.Duration) (string, error)
43→	Capture() string
44→	Close() error
45→}
46→
47→var registry []Agent
48→var gates = map[string]chan struct{}{}
49→
50→func Register(a Agent) {
51→	registry = append(registry, a)
52→}
53→
54→// RegisterGate sets a concurrency limit for an agent's tests.
55→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
56→func RegisterGate(name string, max int) {
57→	gates[name] = make(chan struct{}, max)
58→}
59→
60→// AcquireSlot blocks until a test slot is available for the agent or the
61→// context is cancelled. Returns a non-nil error if the context expires
62→// before a slot opens.
63→func AcquireSlot(ctx context.Context, a Agent) error {
64→	g, ok := gates[a.Name()]
65→	if !ok {
66→		return nil
67→	}
68→	select {
69→	case g <- struct{}{}:
70→		return nil
71→	case <-ctx.Done():
72→		return ctx.Err()
73→	}
74→}
75→
76→// ReleaseSlot frees a test slot for the agent.
77→func ReleaseSlot(a Agent) {
78→	if g, ok := gates[a.Name()]; ok {
79→		<-g
80→	}
81→}
82→
83→func All() []Agent {
84→	return registry
85→}
86→

  1→package agents
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"os"
  7→	"os/exec"
  8→	"path/filepath"
  9→	"strings"
 10→	"syscall"
 11→	"time"
 12→)
 13→
 14→// isolatedConfigDir creates a temp directory that mirrors ~/.claude via
 15→// symlinks but omits CLAUDE.md and skills/ so that test runs don't inherit
 16→// the operator's personal instructions or custom skills.
 17→func isolatedConfigDir() (string, error) {
 18→	home, err := os.UserHomeDir()
 19→	if err != nil {
 20→		return "", fmt.Errorf("get home dir: %w", err)
 21→	}
 22→	src := filepath.Join(home, ".claude")
 23→
 24→	dst, err := os.MkdirTemp("", "claude-config-*")
 25→	if err != nil {
 26→		return "", err
 27→	}
 28→
 29→	entries, err := os.ReadDir(src)
 30→	if err != nil {
 31→		return dst, fmt.Errorf("read %s: %w", src, err)
 32→	}
 33→
 34→	skip := map[string]bool{"CLAUDE.md": true, "skills": true}
 35→	for _, e := range entries {
 36→		if skip[e.Name()] {
 37→			continue
 38→		}
 39→		_ = os.Symlink(filepath.Join(src, e.Name()), filepath.Join(dst, e.Name()))
 40→	}
 41→	return dst, nil
 42→}
 43→
 44→// cleanEnv returns os.Environ() with CLAUDECODE removed so that
 45→// Claude Code doesn't refuse to start inside this test runner.
 46→func cleanEnv() []string {
 47→	var env []string
 48→	for _, e := range os.Environ() {
 49→		if !strings.HasPrefix(e, "CLAUDECODE=") {
 50→			env = append(env, e)
 51→		}
 52→	}
 53→	return env
 54→}
 55→
 56→func init() {
 57→	Register(&Claude{})
 58→}
 59→
 60→type Claude struct{}
 61→
 62→func (c *Claude) Name() string             { return "claude-code" }
 63→func (c *Claude) EntireAgent() string      { return "claude-code" }
 64→func (c *Claude) PromptPattern() string    { return `❯` }
 65→func (c *Claude) TimeoutMultiplier() float64 { return 1.0 }
 66→
 67→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 68→	cfg := &runConfig{Model: "haiku"}
 69→	for _, o := range opts {
 70→		o(cfg)
 71→	}
 72→
 73→	configDir, err := isolatedConfigDir()
 74→	if err != nil {
 75→		return Output{}, fmt.Errorf("create isolated config dir: %w", err)
 76→	}
 77→	defer os.RemoveAll(configDir)
 78→
 79→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
 80→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
 81→	cmd := exec.CommandContext(ctx, "claude", args...)
 82→	cmd.Dir = dir
 83→	cmd.Stdin = nil
 84→	cmd.Env = append(cleanEnv(), "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "CLAUDE_CONFIG_DIR="+configDir)
 85→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 86→	cmd.Cancel = func() error {
 87→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 88→	}
 89→	cmd.WaitDelay = 5 * time.Second
 90→
 91→	var stdout, stderr strings.Builder
 92→	cmd.Stdout = &stdout
 93→	cmd.Stderr = &stderr
 94→
 95→	err = cmd.Run()
 96→	exitCode := 0
 97→	if exitErr, ok := err.(*exec.ExitError); ok {
 98→		exitCode = exitErr.ExitCode()
 99→	}
100→
101→	return Output{
102→		Command:  "claude " + strings.Join(displayArgs, " "),
103→		Stdout:   stdout.String(),
104→		Stderr:   stderr.String(),
105→		ExitCode: exitCode,
106→	}, err
107→}
108→
109→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
110→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
111→	// Interactive sessions rely on macOS Keychain for auth, so we can't
112→	// override CLAUDE_CONFIG_DIR without triggering a login prompt. Prompt
113→	// hardening ("Do not use worktrees") covers interactive tests instead.
114→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "claude", "--dangerously-skip-permissions")
115→	if err != nil {
116→		return nil, err
117→	}
118→
119→	// Dismiss startup dialogs until we reach the input prompt.
120→	for i := 0; i < 5; i++ {
121→		content, err := s.WaitFor(`❯`, 15*time.Second)
122→		if err != nil {
123→			return s, fmt.Errorf("waiting for startup prompt: %w", err)
124→		}
125→		if !strings.Contains(content, "Enter to confirm") {
126→			break
127→		}
128→		// The bypass permissions dialog defaults to "No, exit" —
129→		// arrow down to "Yes, I accept" before confirming.
130→		if strings.Contains(content, "Yes, I accept") {
131→			_ = s.SendKeys("Down")
132→			time.Sleep(200 * time.Millisecond)
133→		}
134→		_ = s.SendKeys("Enter")
135→		time.Sleep(500 * time.Millisecond)
136→	}
137→	s.stableAtSend = ""
138→
139→	return s, nil
140→}
