 11→// RewindPoint represents a single entry from `entire rewind --list`.
 12→type RewindPoint struct {
 13→	ID             string `json:"id"`
 14→	Message        string `json:"message"`
 15→	MetadataDir    string `json:"metadata_dir"`
 16→	Date           string `json:"date"`
 17→	IsLogsOnly     bool   `json:"is_logs_only"`
 18→	CondensationID string `json:"condensation_id"`
