 38→// RewindList runs `entire rewind --list` and parses the JSON output.
 39→func RewindList(t *testing.T, dir string) []RewindPoint {
 40→	t.Helper()
 41→	out := run(t, dir, "rewind", "--list")
 42→
 43→	var points []RewindPoint
 44→	if err := json.Unmarshal([]byte(out), &points); err != nil {
 45→		t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
 46→	}
 47→	return points
 48→}
 49→
 50→// Rewind runs `entire rewind --to <id>`. Returns an error instead of
 51→// failing the test, since callers may test failure cases.
 52→func Rewind(t *testing.T, dir, id string) error {
 53→	t.Helper()
 54→	return runErr(dir, "rewind", "--to", id)
 55→}
 56→
 57→// RewindLogsOnly runs `entire rewind --to <id> --logs-only`.
 58→func RewindLogsOnly(t *testing.T, dir, id string) error {
 59→	t.Helper()
 60→	return runErr(dir, "rewind", "--to", id, "--logs-only")
 61→}
 62→
 63→// run executes an `entire` subcommand in dir and fails the test on error.
 64→func run(t *testing.T, dir string, args ...string) string {
 65→	t.Helper()
 66→	cmd := exec.Command("entire", args...)
 67→	cmd.Dir = dir
 68→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 69→
 70→	out, err := cmd.CombinedOutput()
 71→	if err != nil {
 72→		t.Fatalf("entire %s failed: %v\n%s", strings.Join(args, " "), err, out)
 73→	}
 74→	return strings.TrimSpace(string(out))
 75→}
 76→
 77→// runErr executes an `entire` subcommand in dir and returns any error.
 78→func runErr(dir string, args ...string) error {
 79→	cmd := exec.Command("entire", args...)
 80→	cmd.Dir = dir
 81→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 82→
 83→	out, err := cmd.CombinedOutput()
 84→	if err != nil {
 85→		return &ExecError{
 86→			Args:   args,
 87→			Err:    err,
 88→			Output: string(out),
 89→		}
 90→	}
 91→	return nil
 92→}
 93→
 94→// ExecError wraps an entire CLI execution failure with its output.
 95→type ExecError struct {
 96→	Args   []string
 97→	Err    error
 98→	Output string
 99→}
100→
101→func (e *ExecError) Error() string {
102→	return "entire " + strings.Join(e.Args, " ") + ": " + e.Err.Error() + "\n" + e.Output
103→}
104→
105→func (e *ExecError) Unwrap() error {
106→	return e.Err
107→}
108→
109→// Explain runs `entire explain --checkpoint <id>` and returns the output.
110→func Explain(t *testing.T, dir, checkpointID string) string {
111→	t.Helper()
112→	return run(t, dir, "explain", "--checkpoint", checkpointID)
113→}
114→
115→// ExplainGenerate runs `entire explain --checkpoint <id> --generate`.
116→// Returns (output, error) — doesn't fail test since callers may test failure cases.
117→func ExplainGenerate(dir, checkpointID string) (string, error) {
118→	return runOutput(dir, "explain", "--checkpoint", checkpointID, "--generate")
119→}
120→
121→// ExplainCommit runs `entire explain --commit <ref>`.
122→// Returns (output, error) — for testing failure cases.
123→func ExplainCommit(dir, ref string) (string, error) {
124→	return runOutput(dir, "explain", "--commit", ref)
125→}
126→
127→// runOutput executes an `entire` subcommand and returns (output, error).
128→func runOutput(dir string, args ...string) (string, error) {
129→	cmd := exec.Command("entire", args...)
130→	cmd.Dir = dir
131→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
132→
133→	out, err := cmd.CombinedOutput()
134→	if err != nil {
135→		return string(out), &ExecError{
136→			Args:   args,
137→			Err:    err,
138→			Output: string(out),
139→		}
140→	}
141→	return strings.TrimSpace(string(out)), nil
142→}
