  1→package testutil
  2→
  3→import (
  4→	"fmt"
  5→	"os"
  6→	"os/exec"
  7→	"path/filepath"
  8→	"regexp"
  9→	"strings"
 10→	"testing"
 11→	"time"
 12→)
 13→
 14→// ArtifactRoot is the absolute path to the artifact output directory.
 15→// Must be set in TestMain before any tests run.
 16→var ArtifactRoot string
 17→
 18→// ArtifactTimestamp is the timestamp subdirectory for this test run.
 19→var ArtifactTimestamp = time.Now().Format("2006-01-02T15-04-05")
 20→
 21→var runDirOverride string
 22→
 23→// SetRunDir overrides the artifact run directory (e.g. from E2E_ARTIFACT_DIR).
 24→func SetRunDir(dir string) {
 25→	runDirOverride = dir
 26→}
 27→
 28→// ArtifactRunDir returns the directory for the current test run.
 29→func ArtifactRunDir() string {
 30→	if runDirOverride != "" {
 31→		return runDirOverride
 32→	}
 33→	return filepath.Join(ArtifactRoot, ArtifactTimestamp)
 34→}
 35→
 36→func artifactDir(t *testing.T) string {
 37→	t.Helper()
 38→	name := strings.ReplaceAll(t.Name(), "/", "-")
 39→	dir := filepath.Join(ArtifactRunDir(), name)
 40→	if err := os.MkdirAll(dir, 0o755); err != nil {
 41→		t.Logf("warning: failed to create artifact dir: %v", err)
 42→	}
 43→	return dir
 44→}
 45→
 46→// CaptureArtifacts captures git state, checkpoint metadata, entire logs,
 47→// and console output to the artifact directory.
 48→func CaptureArtifacts(t *testing.T, s *RepoState) {
 49→	t.Helper()
 50→	dir := s.ArtifactDir
 51→
 52→	writeArtifact(t, dir, "git-log.txt",
 53→		gitOutputSafe(s.Dir, "log", "--decorate", "--graph", "--all"))
 54→
 55→	writeArtifact(t, dir, "git-tree.txt",
 56→		gitOutputSafe(s.Dir, "ls-tree", "-r", "HEAD")+
 57→			"\n--- entire/checkpoints/v1 ---\n"+
 58→			gitOutputSafe(s.Dir, "ls-tree", "-r", "entire/checkpoints/v1"))
 59→
 60→	// console.log is written incrementally to disk via s.ConsoleLog (*os.File),
 61→	// so it already exists in the artifact dir and survives global timeouts.
 62→
 63→	if t.Failed() {
 64→		writeArtifact(t, dir, "FAIL", "")
 65→	} else {
 66→		writeArtifact(t, dir, "PASS", "")
 67→	}
 68→
 69→	captureCheckpointMetadata(t, s, dir)
 70→	captureEntireLogs(t, s.Dir, dir)
 71→
 72→	if os.Getenv("E2E_KEEP_REPOS") != "" {
 73→		link := filepath.Join(dir, "repo")
 74→		if err := os.Symlink(s.Dir, link); err != nil {
 75→			t.Logf("warning: failed to symlink repo: %v", err)
 76→		}
 77→	}
 78→}
 79→
 80→func captureCheckpointMetadata(t *testing.T, s *RepoState, outDir string) {
 81→	t.Helper()
 82→	commits := NewCheckpointCommits(t, s)
 83→	metaDir := filepath.Join(outDir, "checkpoint-metadata")
 84→
 85→	cpIDRe := regexp.MustCompile(`(?m)^Checkpoint:\s+(\S+)`)
 86→	for _, sha := range commits {
 87→		msg := gitOutputSafe(s.Dir, "log", "-1", "--format=%B", sha)
 88→		m := cpIDRe.FindStringSubmatch(msg)
 89→		if m == nil || len(m[1]) < 3 {
 90→			continue
 91→		}
 92→		id := m[1]
 93→		cpPath := CheckpointPath(id)
 94→
 95→		cpDir := filepath.Join(metaDir, cpPath)
 96→		_ = os.MkdirAll(cpDir, 0o755)
 97→		raw := gitOutputSafe(s.Dir, "show", sha+":"+cpPath+"/metadata.json")
 98→		writeArtifact(t, cpDir, "metadata.json", raw)
 99→
100→		for i := 0; ; i++ {
101→			sessPath := fmt.Sprintf("%s/%d/metadata.json", cpPath, i)
102→			raw := gitOutputSafe(s.Dir, "show", sha+":"+sessPath)
103→			if raw == "" {
104→				break
105→			}
106→			sessDir := filepath.Join(cpDir, fmt.Sprintf("%d", i))
107→			_ = os.MkdirAll(sessDir, 0o755)
108→			writeArtifact(t, sessDir, "metadata.json", raw)
109→		}
110→	}
111→}
112→
113→func captureEntireLogs(t *testing.T, repoDir, outDir string) {
114→	t.Helper()
115→	logDir := filepath.Join(repoDir, ".entire", "logs")
116→	entries, err := os.ReadDir(logDir)
117→	if err != nil {
118→		return
119→	}
120→	dst := filepath.Join(outDir, "entire-logs")
121→	_ = os.MkdirAll(dst, 0o755)
122→	for _, e := range entries {
123→		data, err := os.ReadFile(filepath.Join(logDir, e.Name()))
124→		if err != nil {
125→			continue
126→		}
127→		writeArtifact(t, dst, e.Name(), string(data))
128→	}
129→}
130→
131→func writeArtifact(t *testing.T, dir, name, content string) {
132→	t.Helper()
133→	path := filepath.Join(dir, name)
134→	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
135→		t.Logf("warning: failed to write artifact %s: %v", path, err)
136→	}
137→}
138→
139→func gitOutputSafe(dir string, args ...string) string {
140→	cmd := exec.Command("git", args...)
141→	cmd.Dir = dir
142→	out, err := cmd.Output()
143→	if err != nil {
144→		return ""
145→	}
146→	return string(out)
147→}
