func (g *Gemini) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("gemini-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, nil, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "gemini", "--model", "gemini-3-flash-preview", "-y")
	if err != nil {
		return nil, err
	}

	// Dismiss startup dialogs (workspace trust, etc.)
	for range 5 {
		content, err := s.WaitFor(`(Type your message|trust)`, 30*time.Second)
		if err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
		}
		if !strings.Contains(content, "trust") {
			break
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}
	s.stableAtSend = ""

	return s, nil
}

