	headHash := env.GetHeadHash()
	worktreeID, err := paths.GetWorktreeID(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to get worktree ID: %v", err)
	}
	return checkpoint.ShadowBranchNameForCommit(headHash, worktreeID)
