		t.Errorf("output should indicate no checkpoint found, got: %s", output)
	}

	// Should still switch to the branch
	if branch := env.GetCurrentBranch(); branch != plainBranch {
		t.Errorf("expected to be on %s, got %s", plainBranch, branch)
	}
}

